// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "td_30", attr: "__html", fn: function () { return ([String(dma_map.get("isuAmt"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("isuAmt")) + " <span id=\"amt_isu_amt\"></span>") : ''); } },
        { childId: "td_412", attr: "__html", fn: function () { return ([String(dma_map.get("equivRedmptVal"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("equivRedmptVal")) + " <span id=\"amt_equiv_redmpt_val\"></span>") : ''); } },
        { childId: "td_509", attr: "__html", fn: function () { return ([String(dma_map.get("secutizSchdlIsuTotamt"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("secutizSchdlIsuTotamt")) + " <span id=\"amt_secutiz_schdl_isu_totamt\"></span>") : ''); } },
        { childId: "td_512", attr: "__html", fn: function () { return ([String(dma_map.get("secutizAsstTotValuAmt"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(dma_map.get("secutizAsstTotValuAmt")) + " <span id=\"amt_secutiz_asst_tot_valu_amt\"></span>") : ''); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_crwfndYn_txt", fn: function(){ return ((dma_map.get("crwfndYn") ?? (() => { throw new Error("unresolved:" + "map.crwfndYn"); })()) ==='Y'); } }, { id: "if_crwfndYn_2_txt", fn: function(){ return ((dma_map.get("crwfndYn") ?? (() => { throw new Error("unresolved:" + "map.crwfndYn"); })()) ==='N'); } }, { id: "if_pcboYn_txt", fn: function(){ return ((dma_map.get("pcboYn") ?? (() => { throw new Error("unresolved:" + "map.pcboYn"); })()) ==='Y'); } }, { id: "if_pcboYn_2_txt", fn: function(){ return ((dma_map.get("pcboYn") ?? (() => { throw new Error("unresolved:" + "map.pcboYn"); })()) ==='N'); } }, { id: "if_pcboYn_3_txt", fn: function(){ return ((dma_map.get("pcboYn") ?? (() => { throw new Error("unresolved:" + "map.pcboYn"); })()) ===''); } }, { id: "if_infllnkYn_txt", fn: function(){ return ((dma_map.get("infllnkYn") ?? (() => { throw new Error("unresolved:" + "map.infllnkYn"); })()) ==='Y'); } }, { id: "if_infllnkYn_2_txt", fn: function(){ return ((dma_map.get("infllnkYn") ?? (() => { throw new Error("unresolved:" + "map.infllnkYn"); })()) ==='N'); } }, { id: "if_hbrdbndYn_txt", fn: function(){ return ((dma_map.get("hbrdbndYn") ?? (() => { throw new Error("unresolved:" + "map.hbrdbndYn"); })()) ==='Y'); } }, { id: "if_hbrdbndYn_2_txt", fn: function(){ return ((dma_map.get("hbrdbndYn") ?? (() => { throw new Error("unresolved:" + "map.hbrdbndYn"); })()) ==='N'); } }, { id: "c_when_193", fn: function(){ return ((dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })()) === 'GB035'); } }, { id: "tr_194", fn: function(){ return ((dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })()) === 'GB035'); } }, { id: "if_crtvlSf1_txt", fn: function(){ return ((dma_crtvlList.get("crtvlSf1") ?? (() => { throw new Error("unresolved:" + "crtvlList.crtvlSf1"); })()) === 'Y'); } }, { id: "if_crtvlSf2_txt", fn: function(){ return ((dma_crtvlList.get("crtvlSf2") ?? (() => { throw new Error("unresolved:" + "crtvlList.crtvlSf2"); })()) === 'Y'); } }, { id: "if_crtvlSf3_txt", fn: function(){ return ((dma_crtvlList.get("crtvlSf3") ?? (() => { throw new Error("unresolved:" + "crtvlList.crtvlSf3"); })()) === 'Y'); } }, { id: "if_crtvlSf4_txt", fn: function(){ return ((dma_crtvlList.get("crtvlSf4") ?? (() => { throw new Error("unresolved:" + "crtvlList.crtvlSf4"); })()) === 'Y'); } }, { id: "if_proftPartcAccYn_txt", fn: function(){ return ((dma_map.get("proftPartcAccYn") ?? (() => { throw new Error("unresolved:" + "map.proftPartcAccYn"); })()) ==='Y'); } }, { id: "if_proftPartcAccYn_2_txt", fn: function(){ return ((dma_map.get("proftPartcAccYn") ?? (() => { throw new Error("unresolved:" + "map.proftPartcAccYn"); })()) ==='N'); } }, { id: "c_when_365", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList")))).length === 0)); } }, { id: "tr_367", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList")))).length === 0)); } }, { id: "c_otherwise_371", fn: function(){ return (!((!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "callList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("callList")))).length === 0)))); } }, { id: "c_when_392", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList")))).length === 0)); } }, { id: "tr_394", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList")))).length === 0)); } }, { id: "c_otherwise_398", fn: function(){ return (!((!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "putList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("putList")))).length === 0)))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_366", entity: "dlt_callList", countIds: [], cells: [{ childId: "__rc83", fn: function (v, i) { return String(v("callExerStrtDate")); } }, { childId: "__rc84", fn: function (v, i) { return String(v("callExerEndDate")); } }] },
        { genId: "c_foreach_393", entity: "dlt_putList", countIds: [], cells: [{ childId: "__rc87", fn: function (v, i) { return String(v("putExerStrtDate")); } }, { childId: "__rc88", fn: function (v, i) { return String(v("putExerEndDate")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb117", fn: function () { return String(dma_map.get("apctTelNo")) + " 내선번호 : " + String(dma_map.get("apctInnrNo")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.setViewTable();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91101.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldinf91101: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf91101.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_self_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.win.closePopup()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91101.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setViewTable
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setViewTable = function () {
    /* sdd-asis-lifecycle:begin setViewTable — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ('' + dma_map.get("nusual_bnd_tp_cd") + '' === "2") {
        $c.util.getComponent("txt_titleNusualBndTpCd").setStyle("display", "");
        $c.util.getComponent("id_nusual_bnd_tp_cd").setStyle("display", "");
    }
    const int_pay_methd_cd = '' + dma_map.get("int_pay_methd_cd") + '';
    if (int_pay_methd_cd === "21" || int_pay_methd_cd === "22" || int_pay_methd_cd === "23") {
        $c.util.getComponent("txt_titleIntPayMethdCd").setStyle("display", "");
        $c.util.getComponent("id_int_pay_methd_cd").setStyle("display", "");
    }
    const imbdopt_corpbnd_cd = '' + dma_map.get("imbdopt_corpbnd_cd") + '';
    if (imbdopt_corpbnd_cd === "1") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_call_option").setStyle("display", "");
    }
    if (imbdopt_corpbnd_cd === "2") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_put_option").setStyle("display", "");
    }
    if (imbdopt_corpbnd_cd === "3") {
        $c.util.getComponent("txt_titleOption").setStyle("display", "");
        $c.util.getComponent("id_call_option").setStyle("display", "");
        $c.util.getComponent("id_put_option").setStyle("display", "");
    }
    const redmpt_methd_tp_cd = '' + dma_map.get("redmpt_methd_tp_cd") + '';
    if (redmpt_methd_tp_cd === "2") {
        $c.util.getComponent("txt_titleRedmptMethdTpCd").setStyle("display", "");
        if ('' + dma_map.get("split_redmpt_tp_cd") + '' === "1" || '' + dma_map.get("split_redmpt_tp_cd") + '' === "2") {
            $c.util.getComponent("id_redmpt_methd_tp_cd").setStyle("display", "");
        } else {
            if ('' + dma_map.get("split_redmpt_tp_cd") + '' === "3") {
                $c.util.getComponent("id_redmpt_methd_tp_cd_list").setStyle("display", "");
            }
        }
    }
    const asst_secutiz_tp_cd = '' + dma_map.get("asst_secutiz_tp_cd") + '';
    if (asst_secutiz_tp_cd !== "") {
        $c.util.getComponent("txt_titleAsstSecutizTpCd").setStyle("display", "");
        $c.util.getComponent("id_asst_secutiz_tp_cd").setStyle("display", "");
    }
    /* sdd-asis-lifecycle:end */
};
